head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf35101";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf35101.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "td_20", attr: "__html", fn: function () { return ([String(dma_map.get("stdCd")), String(dma_map.get("srtCd"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(dma_map.get("stdCd")) + " <strong class=\"\"> (" + String(dma_map.get("srtCd")) + ")</strong>") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_mktNm_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '2'); } }, { id: "if_mktNm_2_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '3'); } }, { id: "if_mktNm_3_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '4'); } }, { id: "if_mktNm_4_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '5'); } }, { id: "if_mktNm_5_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '55'); } }, { id: "if_mktNm_6_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '6'); } }, { id: "if_mktNm_7_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '7'); } }, { id: "if_mktNm_8_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '8'); } }, { id: "if_mktNm_9_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '9'); } }, { id: "if_mktNm_10_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '10'); } }, { id: "if_mktNm_11_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '11'); } }, { id: "if_mktNm_12_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '12'); } }, { id: "if_mktNm_13_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '13'); } }, { id: "if_mktNm_14_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '14'); } }, { id: "if_mktNm_15_txt", fn: function(){ return ((dma_map.get("mktNm") ?? (() => { throw new Error("unresolved:" + "map.mktNm"); })()) === '15'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.setComma();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf35101.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf35101.btn_self_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setComma
 * @description set Comma 처리
 * @returns {void}
 * @hidden N
 */
scwin.setComma = function () {
    $c.num.formatNumber($('#ipt_expPayAmt')[0]);
    $c.num.formatNumber($('#ipt_dcSales')[0]);
    $('#exp_pay_amt_td').text($c.util.getComponent('ipt_expPayAmt').getValue());
    $('#dc_sales_td').text($c.util.getComponent('ipt_dcSales').getValue());
};
